    return list(filter(lambda string: len(string) == size, strings))


def filter_by_substring_and_size(strings: List[str], size: int, substring: str) -> List[str]:
    """ Filter an input list of strings only for ones that have length size and contain given substring
    """
    return list(filter(lambda string: substring in string and len(string) == size, strings))


