def remove_brackets(word: str) -> str:
    """ Removes all brackets from the given word.
    >>> remove_brackets('(some text with brackets)')
    'sometextwithbrackets'
    >>> remove_brackets('some text with brackets')
    'sometextwithbrackets'
    """
    return ''.join(x for x in word if not x == '(' and not x == ')')


def sort_brackets(word: str) -> str:
    """ Returns given string without brackets, sort it and put brackets in the same order.
    >>> sort_brackets('(some text with brackets)')
    'sometextwithbrackets'
    >>> sort_brackets('some text with brackets')
    'sometextwithbrackets'
    """
    word = remove_brackets(word)
    return ''.join(sorted(word))


