def string_to_list(s: str) -> List[int]:
    """ Return list of integers from given string
    >>> string_to_list('1,2,3')
    [1, 2, 3]
    >>> string_to_list('7,23,2')
    [7, 23, 2]
    """
    return list(map(int, s.split(',')))


def list_to_string(s: List[int]) -> str:
    """ Return string from given list of integers.
    """
    return ','.join(map(str, s))


